 @Test void actualHttpEnforcesPublicAntiAbuseAndSignedLeadOwnershipReplayVersionAndNotificationScope()throws Exception{
  String jdbcUrl=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(jdbcUrl!=null,"EXP-LEAD-001 actual HTTP acceptance requires native PostgreSQL");var rg=KeyPairGenerator.getInstance("RSA");rg.initialize(2048);var rsa=rg.generateKeyPair();var eg=KeyPairGenerator.getInstance("EC");eg.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));var ec=eg.generateKeyPair();var jwks=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);String issuer="http://127.0.0.1:"+jwks.getAddress().getPort()+"/realms/offline";jwks.createContext("/",x->{byte[] b=EventCodec.JSON.writeValueAsBytes(Map.of("keys",List.of(new com.nimbusds.jose.jwk.RSAKey.Builder((RSAPublicKey)rsa.getPublic()).keyID("synthetic").algorithm(JWSAlgorithm.RS256).keyUse(KeyUse.SIGNATURE).build().toJSONObject())));x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});jwks.start();
  byte[] anti=new byte[32];Arrays.fill(anti,(byte)5);String antiKey=Base64.getEncoder().encodeToString(anti);var spam=new LocalLeadMocks.AntiSpam(antiKey);var props=new HashMap<String,Object>();props.put("APP_ENV","test");props.put("NIGSON_SECURITY_ENABLED","true");props.put("NIGSON_PRODUCT_PHASE","1");props.put("NIGSON_EVENTS_ENABLED","false");props.put("NIGSON_JDBC_URL",jdbcUrl+"?currentSchema=experience");props.put("NIGSON_DB_USER","nigson_experience_app");props.put("NIGSON_DB_PASSWORD","mock-experience-runtime");props.put("NIGSON_OIDC_ISSUER",issuer);props.put("NIGSON_OIDC_JWKS",issuer+"/protocol/openid-connect/certs");props.put("NIGSON_PRIVATE_PEER_CIDRS","127.0.0.1/32");props.put("NIGSON_ACTOR_PUBLIC_KEYS",EventCodec.JSON.writeValueAsString(Map.of("active",Base64.getEncoder().encodeToString(ec.getPublic().getEncoded()))));props.put("NIGSON_LEAD_RECIPIENT_GROUP","synthetic-sales-triage");props.put("NIGSON_MESSAGING_INBOUND_ENABLED","true");byte[] phoneHash=new byte[32],phoneCipher=new byte[32],inboundCipher=new byte[32];Arrays.fill(phoneHash,(byte)7);Arrays.fill(phoneCipher,(byte)8);Arrays.fill(inboundCipher,(byte)9);props.put("NIGSON_PHONE_CIPHER_REVISION","synthetic");props.put("NIGSON_PHONE_HASH_KEY_VERSION","1");props.put("NIGSON_PHONE_LOCAL_HASH_KEY",Base64.getEncoder().encodeToString(phoneHash));props.put("NIGSON_PHONE_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(phoneCipher));props.put("NIGSON_INBOUND_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(inboundCipher));props.put("NIGSON_INBOUND_RETENTION_DAYS","30");props.put("NIGSON_TWILIO_ACCOUNT_SID","AC0123456789abcdef0123456789abcdef");props.put("NIGSON_TWILIO_AUTH_TOKEN","synthetic-never-live-auth-token-long-enough");props.put("NIGSON_TWILIO_WHATSAPP_FROM","whatsapp:+2348031234567");props.put("NIGSON_TWILIO_WHATSAPP_PUBLIC_URL","https://callbacks.synthetic.invalid/api/v1/webhooks/notifications/twilio/whatsapp");props.put("NIGSON_LEAD_ADMIN_BASE_URL","https://admin.synthetic.invalid");props.put("NIGSON_LEADS_ANTISPAM_MODE","mock");props.put("NIGSON_LEADS_LOCAL_ANTISPAM_HMAC_KEY",antiKey);props.put("NIGSON_LEADS_RATE_LIMIT_MODE","local");props.put("NIGSON_LEADS_RATE_LIMIT_PER_MINUTE","20");props.put("server.port","0");props.put("logging.level.root","WARN");
  try(var app=new SpringApplicationBuilder(ExperienceApplication.class).properties(props).run();var http=HttpClient.newHttpClient()){
   String base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort(),path="/api/v1/enquiries",key=UUID.randomUUID().toString();String invalid="{\"type\":\"CONTACT\",\"name\":\"Synthetic Caller\",\"email\":\"caller@example.invalid\",\"subject\":\"Bad token case\",\"message\":\"private text\",\"antiSpamToken\":\"invalid\"}";JdbcTemplate jdbc=app.getBean(JdbcTemplate.class);long before=jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE subject='HTTP invalid token'",Long.class);var rejected=send(http,base+path,"POST",invalid,UUID.randomUUID().toString(),null,null,null,null);assertThat(rejected.statusCode()).withFailMessage(rejected.body()).isEqualTo(422);assertThat(rejected.body()).doesNotContain("private text","caller@example.invalid");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE subject='HTTP invalid token'",Long.class)).isEqualTo(before);
   String body=EventCodec.JSON.writeValueAsString(Map.of("type","COMPLAINT","name","Synthetic Caller","email","caller@example.invalid","phone","+2348031234567","subject","HTTP complaint","message","private HTTP complaint text","antiSpamToken",spam.sign("syntheticnonce123456",key)));var created=send(http,base+path,"POST",body,key,null,null,null,null);assertThat(created.statusCode()).withFailMessage(created.body()).isEqualTo(201);assertThat(created.headers().firstValue("Cache-Control")).contains("no-store");String replay=send(http,base+path,"POST",body,key,null,null,null,null).body();assertThat(replay).isEqualTo(created.body());UUID id=UUID.fromString(EventCodec.JSON.readTree(created.body()).path("id").asString());String payload=jdbc.queryForObject("SELECT payload::text FROM experience.outbox_event WHERE aggregate_id=? AND event_type='lead.created.v1'",String.class,id);assertThat(payload).doesNotContain("caller@example.invalid","private HTTP complaint text","HTTP complaint");assertThat(EventCodec.decode(payload).path("payload").path("recipient_group").asString()).isEqualTo("synthetic-sales-triage");
   var changed=send(http,base+path,"POST",body.replace("HTTP complaint","Changed HTTP complaint"),key,null,null,null,null);assertThat(changed.statusCode()).isEqualTo(409);
   UUID staff=UUID.randomUUID(),corr=UUID.randomUUID();String list="/api/v1/staff/leads?state=NEW";var listed=send(http,base+list,"GET","",null,workload(rsa,issuer,"nigson-commerce","leads.read_WITH_SIGNED_ACTOR"),actor(ec,issuer,staff,"SALES","leads.read_WITH_SIGNED_ACTOR","GET","/api/v1/staff/leads",corr,new byte[0]),corr,null);assertThat(listed.statusCode()).withFailMessage(listed.body()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(listed.body()).path("items").toString()).contains(id.toString());
   String detailPath="/api/v1/staff/leads/"+id;UUID detailCorr=UUID.randomUUID();var detail=send(http,base+detailPath,"GET","",null,workload(rsa,issuer,"nigson-commerce","leads.read_WITH_SIGNED_ACTOR"),actor(ec,issuer,staff,"SALES","leads.read_WITH_SIGNED_ACTOR","GET",detailPath,detailCorr,new byte[0]),detailCorr,null);assertThat(detail.statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(detail.body()).path("activities").size()).isEqualTo(1);assertThat(EventCodec.JSON.readTree(detail.body()).path("message").asString()).isEqualTo("private HTTP complaint text");
   String patchPath=detailPath,patch="{\"state\":\"ASSIGNED\",\"assignedTo\":\""+staff+"\",\"priority\":\"HIGH\",\"note\":\"Claimed for triage\"}",patchKey=UUID.randomUUID().toString();UUID patchCorr=UUID.randomUUID();String patchWorkload=workload(rsa,issuer,"nigson-commerce","leads.update_WITH_SIGNED_ACTOR"),patchActor=actor(ec,issuer,staff,"SALES","leads.update_WITH_SIGNED_ACTOR","PATCH",patchPath,patchCorr,patch.getBytes(StandardCharsets.UTF_8));var updated=send(http,base+patchPath,"PATCH",patch,patchKey,patchWorkload,patchActor,patchCorr,"\"0\"");assertThat(updated.statusCode()).withFailMessage(updated.body()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(updated.body()).path("version").asLong()).isEqualTo(1);assertThat(updated.headers().firstValue("ETag")).contains("\"1\"");var updateReplay=send(http,base+patchPath,"PATCH",patch,patchKey,patchWorkload,patchActor,patchCorr,"\"0\"");assertThat(updateReplay.statusCode()).isEqualTo(200);assertThat(updateReplay.body()).isEqualTo(updated.body());
   UUID staleCorr=UUID.randomUUID();var stale=send(http,base+patchPath,"PATCH",patch,UUID.randomUUID().toString(),workload(rsa,issuer,"nigson-commerce","leads.update_WITH_SIGNED_ACTOR"),actor(ec,issuer,staff,"SALES","leads.update_WITH_SIGNED_ACTOR","PATCH",patchPath,staleCorr,patch.getBytes(StandardCharsets.UTF_8)),staleCorr,"\"0\"");assertThat(stale.statusCode()).isEqualTo(412);
   UUID other=UUID.randomUUID(),otherCorr=UUID.randomUUID();var denied=send(http,base+detailPath,"GET","",null,workload(rsa,issuer,"nigson-commerce","leads.read_WITH_SIGNED_ACTOR"),actor(ec,issuer,other,"SALES","leads.read_WITH_SIGNED_ACTOR","GET",detailPath,otherCorr,new byte[0]),otherCorr,null);assertThat(denied.statusCode()).isEqualTo(404);
   UUID contextCorr=UUID.randomUUID();var context=send(http,base+"/internal/v1/leads/"+id+"/notification-context","GET","",null,workload(rsa,issuer,"nigson-integration","notification.read"),null,contextCorr,null);assertThat(context.statusCode()).withFailMessage(context.body()).isEqualTo(200);var dto=EventCodec.JSON.readTree(context.body());assertThat(dto.path("recipientGroup").asString()).isEqualTo("synthetic-sales-triage");assertThat(dto.path("adminLink").asString()).isEqualTo("https://admin.synthetic.invalid/staff/leads/"+id);assertThat(dto.toString()).doesNotContain("private HTTP complaint text","caller@example.invalid");
   UUID wrongCorr=UUID.randomUUID();var wrong=send(http,base+detailPath,"GET","",null,workload(rsa,issuer,"nigson-commerce","quote.read"),actor(ec,issuer,staff,"SALES","leads.read_WITH_SIGNED_ACTOR","GET",detailPath,wrongCorr,new byte[0]),wrongCorr,null);assertThat(wrong.statusCode()).isIn(401,403);
  }finally{jwks.stop(0);}
 }
 private static String workload(KeyPair rsa,String issuer,String client,String scope)throws Exception{var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).keyID("synthetic").build(),new JWTClaimsSet.Builder().issuer(issuer).subject("synthetic-workload").audience("nigson-experience").claim("typ","Bearer").claim("client_id",client).claim("azp",client).claim("scope",scope).issueTime(new Date()).expirationTime(Date.from(Instant.now().plusSeconds(120))).build());jwt.sign(new RSASSASigner((RSAPrivateKey)rsa.getPrivate()));return jwt.serialize();}
 private static String actor(KeyPair ec,String issuer,UUID party,String role,String scope,String method,String path,UUID corr,byte[] body)throws Exception{var a=new ActorAssertion.Actor(party,issuer,"lead-actor",null,Set.of(role),Set.of(scope),null);var binding=new ActorAssertion.Binding("experience",scope,method,path,corr,ActorAssertion.Binding.bodyHash(body));var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID("active").type(new JOSEObjectType("nigson-actor+jwt")).build(),ActorAssertion.claims(a,binding,Instant.now()));jwt.sign(new ECDSASigner((ECPrivateKey)ec.getPrivate()));return jwt.serialize();}
 private static HttpResponse<String> send(HttpClient http,String url,String method,String body,String key,String bearer,String actor,UUID corr,String ifMatch)throws Exception{var b=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("X-Correlation-ID",corr==null?UUID.randomUUID().toString():corr.toString());if(bearer!=null)b.header("Authorization","Bearer "+bearer);if(actor!=null)b.header("X-Nigson-Actor",actor);if(key!=null)b.header("Idempotency-Key",key);if(ifMatch!=null)b.header("If-Match",ifMatch);if(method.equals("POST")||method.equals("PATCH"))b.header("Content-Type","application/json");return http.send(b.method(method,body==null||body.isEmpty()?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
